#include <stdio.h>

char toggle(char c) {
    if (c >= 'a' && c <= 'z') return c - 'a' + 'A';
    if (c >= 'A' && c <= 'Z') return c - 'A' + 'a';
    return c;
}

int main() {
    char s[] = "Zebra and Alpha";
    for (int i = 0; s[i] != '\0'; i++) {
        s[i] = toggle(s[i]);
    }
    printf("%s\n", s);
    return 0;
}
